(root/'login_isolated_v2.py').write_text('"""One selected account; use current Okad authentication without publishing a new Cookie."""\nimport json,sys,hashlib,contextlib,io,datetime\nsys.path.insert(0,"/app/backend")\ncfg=json.load(sys.stdin)\nassert (cfg[\'account_id\'],cfg[\'member_id\']) in [(1739,1259),(1741,248),(1743,246)]\nfrom app.services import external_login\nfrom app.services import firefly\ncaptured={};safe_events=[]\ndef log(message):\n markers=[x for x in [\'登录成功\',\'修复路线\',\'原路线\',\'会话\',\'验证码\',\'冷却\',\'Cookie\',\'captcha\',\'401\',\'403\',\'429\'] if x.lower() in str(message).lower()]\n if markers:safe_events.append({\'at\':datetime.datetime.now(datetime.timezone.utc).isoformat(),\'markers\':markers})\noriginal=external_login._login_with_proxy_retry\n\ndef fixed(**kw):\n assert kw[\'email\'].lower()==cfg[\'email\'].lower()\n kw[\'proxy_raw\']=cfg[\'proxy\'];kw[\'network_retries\']=0\n return original(**kw)\nexternal_login._login_with_proxy_retry=fixed\nexternal_login.proxy_pool.random_proxy=lambda raw,**kw:cfg[\'proxy\']\n\ndef save_success(member_id,rec,*args,**kwargs):\n assert member_id==cfg[\'member_id\'];captured[\'record\']=rec\nexternal_login._save_success=save_success\nexternal_login._save_failure=lambda member_id,*args,**kwargs:None\n# Do not change passwords or complete profiles during a comparison.\ndef blocked_completion(*args,**kwargs):raise RuntimeError(\'diagnostic_profile_or_password_change_not_allowed\')\nfirefly._adm.complete_sub_account=blocked_completion\nfirefly._cleanup_profile_organizations=blocked_completion\nfrom app.services import organization_cleanup\n_original_activation=organization_cleanup.activate_del_invitation\ndef guarded_activation(auth,links,*args,**kwargs):\n if any(organization_cleanup.is_del_organization(x.get(\'description\')) for x in links if isinstance(x,dict)):\n  raise RuntimeError(\'diagnostic_organization_change_not_allowed\')\n return _original_activation(auth,links,*args,**kwargs)\norganization_cleanup.activate_del_invitation=guarded_activation\noriginal_cookie=firefly._adm._session_cookie_str\n\ndef cookie_capture(client):\n cookie=original_cookie(client)\n jar=getattr(getattr(client,\'session\',None),\'cookies\',None)\n jar=getattr(jar,\'jar\',jar)\n items=[]\n try:\n  for c in jar:\n   if not getattr(c,\'name\',None):continue\n   x={\'name\':c.name,\'value\':c.value,\'domain\':c.domain,\'path\':c.path or \'/\',\'secure\':bool(c.secure),\'httpOnly\':any(k.lower()==\'httponly\' for k in getattr(c,\'_rest\',{})),\'sameSite\':next((str(v).capitalize() for k,v in getattr(c,\'_rest\',{}).items() if k.lower()==\'samesite\' and str(v).lower() in [\'lax\',\'strict\',\'none\']),\'Lax\')}\n   if c.expires and c.expires>0:x[\'expires\']=c.expires\n   items.append(x)\n except Exception:pass\n captured[\'cookies\']=items\n return cookie\nfirefly._adm._session_cookie_str=cookie_capture\ntry:\n # Python module logging is captured locally, never returned with credential values.\n sink=io.StringIO()\n with contextlib.redirect_stdout(sink),contextlib.redirect_stderr(sink):\n  result=external_login.login_and_store(cfg[\'member_id\'],automatic=False,network_retries=0,sync_to_sub2=False,log=log)\n rec=captured.get(\'record\') or {}\n out={\'ok\':result.get(\'ok\') is True and bool(rec.get(\'access_token\')),\'code\':result.get(\'code\'),\'events\':safe_events,\'account_id\':cfg[\'account_id\'],\'record\':rec,\'cookies\':captured.get(\'cookies\',[])}\nexcept BaseException as e:\n import traceback\n out={\'ok\':False,\'account_id\':cfg[\'account_id\'],\'error_class\':type(e).__name__,\'frames\':[{\'file\':x.filename.split(\'/\')[-1],\'name\':x.name,\'line\':x.lineno} for x in traceback.extract_tb(e.__traceback__)][-8:],\'events\':safe_events}\nprint(\'PRIVATE_RESULT:\'+json.dumps(out,ensure_ascii=False))\n')
(root/'warmup_v2.py').write_text('import json,subprocess,pathlib,datetime,time,sqlite3,hashlib,urllib.request,urllib.error,urllib.parse,os,sys,traceback,signal,threading\nROOT=pathlib.Path(\'/opt/adobe-relay/releases/three-arm-20261027\');IDS=[1739,1741,1743];MEMBERS={1742:247,1744:245,1749:240,1758:231};EXPECTED=\'adobe-relay:df07b90d7e2ce8e27fd7a9deb11336eaf5077e3c\';os.umask(0o077)\ndef now():return datetime.datetime.now(datetime.timezone.utc).isoformat()\ndef log(kind,**kw):\n with (ROOT/\'controller.jsonl\').open(\'a\') as f:f.write(json.dumps({\'at\':now(),\'event\':kind,**kw},ensure_ascii=False)+\'\\n\')\ndef sql(q,raw=False):\n r=subprocess.run([\'docker\',\'exec\',\'-i\',\'adobe-relay-postgres-1\',\'psql\',\'-U\',\'sub2api\',\'-d\',\'sub2api\',\'-Atq\',\'-v\',\'ON_ERROR_STOP=1\'],input="BEGIN READ ONLY;SET LOCAL statement_timeout=\'8s\';"+q+\';COMMIT;\',capture_output=True,text=True,timeout=15)\n if r.returncode:raise RuntimeError(\'database_read_failed\')\n return r.stdout.strip() if raw else [json.loads(x) for x in r.stdout.splitlines() if x.startswith(\'{\')]\ndef api(method,path,body=None,timeout=35):\n assert path==\'/api/v1/admin/accounts/bulk-update\' or any(path==f\'/api/v1/admin/accounts/{i}\'+suffix for i in IDS for suffix in (\'\',\'/schedulable\',\'/test\'))\n if path.endswith(\'bulk-update\'):assert set(body[\'account_ids\'])<=set(IDS) and \'filters\' not in body\n key=sql("SELECT value FROM settings WHERE key=\'admin_api_key\'",True)\n req=urllib.request.Request(\'http://127.0.0.1:6666\'+path,data=json.dumps(body).encode() if body is not None else None,headers={\'x-api-key\':key,\'Content-Type\':\'application/json\',\'X-Request-ID\':\'session-controlled-20261027\'},method=method)\n with urllib.request.urlopen(req,timeout=timeout) as r:\n  if path.endswith(\'/test\'):\n   result=[]\n   for line in r:\n    if line.startswith(b\'data: \'):\n     d=json.loads(line[6:]);result.append({k:d[k] for k in [\'type\',\'success\',\'status_code\'] if k in d})\n   return result\n  d=json.load(r);return {\'code\':d.get(\'code\'),\'success_ids\':(d.get(\'data\') or {}).get(\'success_ids\')} if isinstance(d,dict) else {}\ndef rows(private=False):\n q="SELECT json_build_object(\'id\',a.id,\'email\',a.name,\'status\',a.status,\'schedulable\',a.schedulable,\'concurrency\',a.concurrency,\'manual_pause\',a.extra->\'okad_manual_pause\',\'manual_proxy\',a.extra->\'manual_proxy_enabled\',\'proxy_id\',a.proxy_id,\'proxy_updated_at\',p.updated_at,\'proxy_status\',p.status,\'proxy_excluded\',EXISTS(SELECT 1 FROM adobe_route_exclusions e WHERE e.proxy_id=a.proxy_id),\'other_bindings\',(SELECT count(*) FROM accounts b WHERE b.deleted_at IS NULL AND b.proxy_id=a.proxy_id AND b.id<>a.id),\'active_lease\',EXISTS(SELECT 1 FROM adobe_proxy_test_leases l WHERE l.account_id=a.id AND l.expires_at>NOW()),\'version\',a.extra->\'okad\'->\'version\',\'verification\',a.extra->\'okad\'->\'verification\',\'test\',a.extra->\'okad_connection_test\',\'error\',a.error_message,\'cookie_hash\',md5(a.credentials->>\'cookie\'),\'runtime_cookie_hash\',md5(a.credentials->>\'adobe_session_cookie\'),\'token_hash\',md5(a.credentials->>\'access_token\'),\'token\',a.credentials->>\'access_token\',\'arp_session_id\',a.credentials->>\'arp_session_id\',\'proxy\',json_build_object(\'host\',p.host,\'port\',p.port,\'protocol\',p.protocol,\'username\',p.username,\'password\',p.password)) FROM accounts a LEFT JOIN proxies p ON p.id=a.proxy_id WHERE a.deleted_at IS NULL AND a.id IN ("+\',\'.join(map(str,IDS))+\') ORDER BY a.id\'\n data=sql(q)\n if not private:\n  for a in data:\n   for k in [\'token\',\'arp_session_id\',\'proxy\']:a.pop(k,None)\n return data\ndef save(name,data):\n p=ROOT/name;tmp=ROOT/(name+\'.tmp\');tmp.write_text(json.dumps(data,ensure_ascii=False,indent=2));tmp.replace(p)\ndef others():\n return sql("SELECT json_build_object(\'id\',id,\'config_hash\',md5(json_build_object(\'concurrency\',concurrency,\'priority\',priority,\'groups\',(SELECT json_agg(group_id ORDER BY group_id) FROM account_groups WHERE account_id=accounts.id),\'manual_pause\',extra->\'okad_manual_pause\',\'manual_proxy\',extra->\'manual_proxy_enabled\')::text),\'cookie_hash\',md5(credentials->>\'cookie\')) FROM accounts WHERE deleted_at IS NULL AND id NOT IN ("+\',\'.join(map(str,IDS))+\') ORDER BY id\')\n\n\n\nimport concurrent.futures\nPRIVATE=pathlib.Path(\'/dev/shm/adobe-three-arm-20261027-private.json\')\nMEMBERS={1739:1259,1741:248,1743:246}\ndef proxy_url(p):\n auth=(urllib.parse.quote(p.get(\'username\') or \'\',safe=\'\')+\':\'+urllib.parse.quote(p.get(\'password\') or \'\',safe=\'\')+\'@\') if p.get(\'username\') else \'\'\n return p[\'protocol\']+\'://\'+auth+p[\'host\']+\':\'+str(p[\'port\'])\ndef one(a):\n cfg={\'account_id\':a[\'id\'],\'member_id\':MEMBERS[a[\'id\']],\'email\':a[\'email\'],\'proxy\':proxy_url(a[\'proxy\'])}\n cmd=[\'docker\',\'run\',\'--rm\',\'-i\',\'--name\',f"adobe-three-arm-login-{a[\'id\']}",\'--network\',\'adobe-relay_default\',\'--memory\',\'512m\',\'--cpus\',\'0.5\',\'--read-only\',\'--tmpfs\',\'/tmp:rw,size=32m\',\'--mount\',\'type=bind,src=/opt/adobe-team-cookie/data,dst=/app/data\',\'--mount\',f\'type=bind,src={ROOT},dst=/experiment,readonly\',\'-e\',\'DATABASE_URL=sqlite:////app/data/app.db\',\'--entrypoint\',\'python\',\'adobe-team-cookie:79382b0f79d559575956e023dc9f52fbf07dbfde\',\'/experiment/login_isolated_v2.py\']\n r=subprocess.run(cmd,input=json.dumps(cfg),text=True,capture_output=True,timeout=350)\n records=[x[len(\'PRIVATE_RESULT:\'):] for x in r.stdout.splitlines() if x.startswith(\'PRIVATE_RESULT:\')]\n if not records:return {\'account_id\':a[\'id\'],\'ok\':False,\'error_class\':\'login_process_failed\',\'returncode\':r.returncode}\n result=json.loads(records[-1]);result.update(proxy=cfg[\'proxy\'],proxy_id=a[\'proxy_id\'],email=a[\'email\']);return result\ntry:\n assert not (ROOT/\'auth-started.json\').exists() and not PRIVATE.exists(),\'no replay of unknown login outcome\'\n current=rows(True)\n assert {a[\'id\'] for a in current}==set(IDS)\n for a in current:\n  assert a[\'manual_pause\'] is True and a[\'manual_proxy\'] is True and not a[\'schedulable\'] and not a[\'active_lease\'] and not a[\'other_bindings\']\n  assert a[\'proxy_id\']=={1739:1398,1741:1324,1743:1333}[a[\'id\']]\n save(\'auth-started.json\',{\'at\':now(),\'ids\':IDS});save(\'auth-baseline.json\',rows())\n with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:results=list(pool.map(one,current))\n safe=[]\n for r in results:\n  record=r.get(\'record\') or {};cookie=record.get(\'cookie\') or \'\';token=record.get(\'access_token\') or \'\'\n  safe.append({k:v for k,v in r.items() if k in [\'account_id\',\'ok\',\'code\',\'error_class\',\'returncode\',\'events\',\'proxy_id\',\'frames\']}|{\'token_hash\':hashlib.sha256(token.encode()).hexdigest()[:24] if token else None,\'cookie_hash\':hashlib.sha256(cookie.encode()).hexdigest()[:24] if cookie else None,\'cookie_jar_count\':len(r.get(\'cookies\') or [])})\n save(\'auth-results.json\',{\'at\':now(),\'results\':safe})\n if not all(r.get(\'ok\') and r.get(\'cookies\') for r in results):raise RuntimeError(\'not_all_authentication_succeeded\')\n PRIVATE.write_text(json.dumps(results));os.chmod(PRIVATE,0o600)\n save(\'auth-ready.json\',{\'at\':now(),\'ids\':IDS,\'private_state\':\'tmpfs_root_only\',\'sub2_cookie_pushes\':0})\nexcept BaseException as e:save(\'auth-failed.json\',{\'at\':now(),\'error_class\':type(e).__name__,\'reason\':str(e)[:150]})\n')
